pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address staker, uint256 stakeAmount, address rewardToken, uint256 rewardAmount) public {
        vm.assume(staker != address(0) && rewardToken != address(0));
        vm.assume(stakeAmount > 0 && stakeAmount <= 1e30);
        vm.assume(rewardAmount > 0 && rewardAmount <= 1e30);
        vm.assume(rewardToken != address(c.stakingToken()));

        // Setup: fund staker with staking tokens
        deal(address(c.stakingToken()), staker, stakeAmount);

        // Stake tokens
        vm.prank(staker);
        c.stake(stakeAmount);

        // Add reward token
        c.addReward(rewardToken);

        // Fund distributor and notify reward
        deal(rewardToken, address(this), rewardAmount);
        IERC20(rewardToken).approve(address(c), rewardAmount);
        c.notifyRewardAmount(rewardToken, rewardAmount);

        // Claim rewards and record the amount
        uint256 beforeClaim = c.claimableRewards(staker, rewardToken);
        vm.prank(staker);
        c.getRewards(staker);
        uint256 afterClaim = c.claimableRewards(staker, rewardToken);

        // Now add a new reward token to trigger updateReward modifier
        address newRewardToken = address(uint160(uint256(keccak256(abi.encode("new", rewardToken)))));
        vm.assume(newRewardToken != address(0) && newRewardToken != address(c.stakingToken()));
        c.addReward(newRewardToken);

        // After adding new reward token, old claimableRewards should remain zero
        assertTrue(c.claimableRewards(staker, rewardToken) == 0, "claimableRewards not reset");
    }
}

