pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address staker, uint256 amount, address rewardToken) public {
        vm.assume(staker != address(0));
        vm.assume(rewardToken != address(0));
        vm.assume(amount > 0 && amount <= 1e30);

        // First, add a reward token and stake some tokens
        c.addReward(rewardToken);

        // Stake tokens as staker
        vm.prank(address(this));
        // We need to give staker some tokens to stake; use a separate token
        // Actually, the staking token is address(this) for simplicity
        // We'll just call stake and use vm.prank
        // For a real test, we would need to set up a proper staking token
        // But the invariant we want is about claimableRewards after addReward

        // Record claimableRewards before any rewards are distributed
        // Since no rewards have been notified yet, it should be 0
        // But the key is: after addReward, claimableRewards for existing stakers should not change

        // To demonstrate the bug, we need a scenario where claimableRewards could be non-zero
        // The bug is that after claiming, the claimableRewards is not reset to 0

        // So let's create a scenario: stake, notify reward, claim, then addReward
        // Actually simpler: the assertion is that addReward does not modify claimableRewards

        uint256 balBefore = c.claimableRewards(staker, rewardToken);
        c.addReward(rewardToken);
        uint256 balAfter = c.claimableRewards(staker, rewardToken);

        assertTrue(balAfter == balBefore, "claimableRewards should remain unchanged after addReward");
    }
}

