pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address staker, address rewardToken) public {
        vm.assume(staker != address(0));
        vm.assume(rewardToken != address(0));

        // Add reward token if not already added
        (bool success,) = address(c).call(abi.encodeWithSignature("addReward(address)", rewardToken));
        if (!success) return; // Already exists, skip

        // Stake some tokens to become a staker
        c.stakeFor(staker, 1e18);

        // Ensure no reward is claimable initially
        uint256 initialClaimable = c.claimableRewards(staker, rewardToken);

        // Now call getReward to simulate a claim (will do nothing because amount is 0)
        c.getReward(staker, rewardToken);

        // Add the same reward token again (this is the key operation)
        (bool success2,) = address(c).call(abi.encodeWithSignature("addReward(address)", rewardToken));
        if (success2) {
            // After addReward, the claimable amount for this staker should remain unchanged (zero)
            assertTrue(c.claimableRewards(staker, rewardToken) == initialClaimable);
        }
    }
}

