pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address staker, address rewardToken) public {
        // Ensure rewardToken is a valid token address (non-zero)
        vm.assume(rewardToken != address(0));

        // Ensure staker is not the zero address (to avoid edge cases)
        vm.assume(staker != address(0));

        // Add the reward token first (as owner)
        c.addReward(rewardToken);

        // Read claimableRewards before any other action
        uint256 before = c.claimableRewards(staker, rewardToken);

        // Call addReward again (should revert as it already exists)
        // This is just to trigger the updateReward modifier which might change state
        // But we can't call it again, so we call a no-op that updates
        // Actually, the rule is: after addReward, claimableRewards for any staker/token should not differ from before
        // Since addReward only initializes the reward token, it does not touch claimableRewards for any staker
        // So the general rule is that claimableRewards remains 0 for any staker/token pair

        // After addReward, claimableRewards should be 0 for any staker and this token
        // In the reference, it stays 0. In the buggy version, it might be changed due to the unsafe transfer
        // but here we test that it is unchanged from its initial value (0)

        uint256 after = c.claimableRewards(staker, rewardToken);

        // General rule: claimableRewards does not change when adding a reward token
        assertTrue(before == after, "claimableRewards changed after addReward");
    }
}

