import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account) public {
        vm.assume(account != address(0) && account != address(c));
        // add a reward token
        c.addReward(address(0x1234));
        // The buggy version: balanceOf(account) returns totalSupply() regardless of actual balance
        // The reference: balanceOf(account) returns _balances[account], which is 0 for any account that never staked
        // But totalSupply is also 0 at this point (no stakes), so both return 0.
        // To distinguish, we first stake some amount for account, then add a reward token and check balanceOf.
        // However, the test must be general: we can check that balanceOf(account) is always equal to totalSupply() for any account.
        // Actually, in the reference, balanceOf(account) is only equal to totalSupply() when account is the only staker with the entire supply.
        // That's not a general rule. Let's rethink.
        // The bug makes balanceOf(account) always return totalSupply for any account.
        // A general rule that holds on reference but fails on mutant: For any account, balanceOf(account) <= totalSupply().
        // In the reference, an account's balance is at most totalSupply. In the bug, balanceOf(account) == totalSupply, so it's also <= totalSupply.
        // That doesn't catch the bug. We need something else.
        // The bug: balanceOf returns totalSupply for any account. So if we have two different accounts with different actual balances,
        // balanceOf(account1) and balanceOf(account2) should differ in reference but be equal in mutant.
        // So we can test: For any two accounts a and b, balanceOf(a) - balanceOf(b) == actualBalanceDifference.
        // But we cannot read actual balances directly. Instead, we can use the contract's own totalSupply and the fact that balances sum to totalSupply.
        // Actually, the sum of balances of all accounts equals totalSupply. But we can't iterate all accounts.
        // Simpler: For any account that never interacted, balanceOf(account) == 0 in reference but == totalSupply in mutant.
        // So after adding a reward token (which doesn't change balances), if totalSupply > 0, then balanceOf(any new account) is 0 in reference, but totalSupply in mutant.
        // We can ensure totalSupply > 0 by staking first.
        uint256 stakeAmount = 100;
        deal(address(c.stakingToken()), address(this), stakeAmount); // give this contract some tokens
        c.stake(stakeAmount);
        // Now totalSupply = stakeAmount > 0
        // Add reward token
        c.addReward(address(0x1234));
        // Now for a random account that never staked, balanceOf should be 0 in reference, but stakeAmount in mutant.
        // So the rule: after addReward, balanceOf(account) == 0 for any account that is not a staker.
        // But we can't know if account is a staker. However, we can pick an account that we know hasn't staked: e.g., address(0xdead).
        // But then it's hard-coded. Instead, we can use the fact that the only staker is this contract (address(this)).
        // So for any other account (including zero address?), balanceOf should be 0 in reference.
        // Actually, zero address might have balance in reference if someone sent tokens? Not relevant.
        // So: after staking and adding reward, for any address != address(this), balanceOf == 0 in reference, but in mutant it equals totalSupply.
        // But the test must work for any fuzz input. So we choose account = a random address, and assume it's not the staker.
        vm.assume(account != address(this));
        // Also assume account != address(c) (the contract itself, but that's irrelevant)
        uint256 bal = c.balanceOf(account);
        uint256 total = c.totalSupply();
        // In reference: bal == 0 (since account never staked). In mutant: bal == total (since bug makes it return totalSupply).
        // So the rule is: bal == 0  (which holds for reference but fails for mutant when total > 0)
        assertTrue(bal == 0, "balanceOf should be 0 for non-staker");
    }
}

