// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        // Ensure token not already added
        (uint40 periodFinish,,,,) = c.rewardData(rewardToken);
        vm.assume(periodFinish == 0);
        c.addReward(rewardToken);
        // After addReward, rewardPerTokenStored should be 0
        (,,, uint216 rewardPerTokenStored) = c.rewardData(rewardToken);
        assertTrue(rewardPerTokenStored == 0);
    }
}

