pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        vm.assume(rewardToken != address(c.stakingToken()));

        // Ensure the token hasn't been added already (avoid revert)
        // We'll use a try/catch to handle the case where it's already added (unlikely in fuzz)
        try c.addReward(rewardToken) {
            // After addReward, the rewardRate must be 0 because no rewards have been notified yet
            // We can read rewardData's rewardRate via the autogenerated getter for the struct
            (uint40 periodFinish, uint216 rewardRate, uint40 lastUpdateTime, uint216 rewardPerTokenStored) = c.rewardData(rewardToken);
            assertTrue(rewardRate == 0, "rewardRate should be zero after addReward");
        } catch {
            // If addReward reverts (e.g., token already exists), the property is vacuously true
        }
    }
}

