    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        vm.assume(rewardToken != address(c));
        vm.assume(rewardToken.code.length > 0); // must be a contract to avoid revert in safeTransferFrom later
        // Ensure token not already added
        (uint40 periodFinish, uint216 rewardRate, uint40 lastUpdateTime, uint216 rewardPerTokenStored) = c.rewardData(rewardToken);
        vm.assume(lastUpdateTime == 0);

        c.addReward(rewardToken);

        uint256 rpt = c.rewardPerToken(rewardToken);
        assertTrue(rpt == 0, "rewardPerToken should be 0 after addReward");
    }
}

