pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address _rewardToken) public {
        // Restrict inputs: must be a non-zero address and not the token itself (to avoid collisions)
        vm.assume(_rewardToken != address(0));
        vm.assume(_rewardToken != address(c));
        // Ensure the token has not been added yet
        (,, uint256 lastUpdateTime,,) = c.rewardData(_rewardToken);
        vm.assume(lastUpdateTime == 0);

        // Call addReward
        c.addReward(_rewardToken);

        // After addReward, rewardPerTokenStored should be zero because no reward has been notified
        (,,, uint256 storedPerToken,) = c.rewardData(_rewardToken);
        assertTrue(storedPerToken == 0);
    }
}
